+void OpenconnectSettingWidget::selectTokenCertificate()
+{
+#ifdef HAVE_P11KIT
+    Q_D(OpenconnectSettingWidget);
+
+    const QList<TokenCertificate> certificates = tokenCertificates();
+    if (certificates.isEmpty()) {
+        KMessageBox::information(this, i18n("No certificates were found on smart cards or security tokens."));
+        return;
+    }
+
+    QStringList labels;
+    for (const TokenCertificate &certificate : certificates) {
+        labels.append(certificate.label);
+    }
+
+    bool ok = false;
+    const QString label = QInputDialog::getItem(this, i18nc("@title:window", "Select Certificate"), i18n("Certificate:"), labels, 0, false, &ok);
+    if (!ok) {
+        return;
+    }
+
+    // OpenConnect finds the private key next to the certificate on the token
+    d->ui.leUserCert->setText(certificates.at(labels.indexOf(label)).uri);
+    d->ui.leUserPrivateKey->clear();
+#endif
+}
